#include <cstdio>
#include <vector>
#include <string>
#include <iostream>

int main() {
    std::string tk;
    std::vector<long long> st;
    while (std::cin >> tk) {
        if (tk == "+" || tk == "-" || tk == "*" || tk == "/") {
            long long b = st.back(); st.pop_back();
            long long a = st.back(); st.pop_back();
            long long r = 0;
            if (tk == "+") r = a + b;
            else if (tk == "-") r = a - b;
            else if (tk == "*") r = a * b;
            else r = a / b;              // C++ 整数除法即向零截断
            st.push_back(r);
        } else {
            st.push_back(std::stoll(tk));
        }
    }
    printf("%lld\n", st.back());
    return 0;
}
